const items = $input.all();

return items.map(item => {
  const body = item.json.body || {};
  const context = body.context || {};
  const issue = context.paperclipIssue || {};

  // Lấy lý do đánh thức (wakeReason hoặc wakeSource) từ Paperclip
  const wakeReason = body.wakeReason || context.wakeReason || "";
  const wakeSource = body.wakeSource || context.wakeSource || "";

  // Trạng thái hiện tại của task
  const status = issue.status || "";

  // 1. Chạy lần đầu tiên khi mới giao việc
  const isInitialRun = (wakeReason === "issue_assigned" || status === "todo");

  // 2. Chạy lại khi HR VSS hoặc các sub-task con đã hoàn thành xong (Blocker resolved)
  const isBlockerResolved = (wakeReason === "issue_blockers_resolved" || wakeSource === "automation");

  return {
    json: {
      taskId: body.taskId || context.issueId || "",
      wakeReason,
      wakeSource,
      status,
      isInitialRun,
      isBlockerResolved,
      // Thêm flag kiểm tra đúng định dạng tiêu đề để tránh chạy nhầm task khác
      isCorrectTitle: (issue.title || "").toLowerCase().includes("thử việc") || (issue.title || "").toLowerCase().includes("hđlđ")
    }
  };
});

