// Lọc ra các item hợp lệ (có chứa id task)
const childTasks = $input.all().map(item => item.json).filter(t => t && t.id);

// Phase 1: Không có task con nào (hoặc danh sách rỗng) -> Khởi tạo
if (childTasks.length === 0) {
  return [{ json: { route: "Phase 1: Initial Run" } }];
}

// Phase 3: Đã có task Báo Cáo (Contract) và nó đã DONE -> Xong toàn bộ
const contractTask = childTasks.find(t => t.title && t.title.toLowerCase().includes("báo cáo"));
if (contractTask && contractTask.status === "done") {
  return [{ json: { route: "Phase 3: Chiến dịch hoàn tất" } }];
}

// Phase 2: Có task HR VSS và nó đã DONE -> HR vừa làm xong
const hrTask = childTasks.find(t => t.title && t.title.toLowerCase().includes("cập nhật"));
if (hrTask && hrTask.status === "done") {
  return [{ json: { route: "Phase 2: HR đã cập nhật xong" } }];
}

// Mặc định
return [{ json: { route: "Đang chờ..." } }];

